import type { Metadata } from "next";

// Absolute base for share links, sitemap and structured data. Set MIAS_SITE_URL once a domain is approved;
// until then the local preview origin is used and these outputs are not launch artifacts.
export const siteUrl = process.env.MIAS_SITE_URL ?? "http://127.0.0.1:3000";

// Generated by app/opengraph-image.tsx. Named explicitly because a page's own openGraph replaces the inherited image.
const shareImage = { url: "/opengraph-image", width: 1200, height: 630, alt: "Mias Energy Solutions: water, electrical and renewable energy services in Lusaka, Zambia" };

/** Page title/description plus matching Open Graph and Twitter previews. */
export function pageMetadata(title: string, description: string, path: string): Metadata {
  return {
    title, description,
    openGraph: { title, description, url: path, siteName: "Mias Energy Solutions", locale: "en_ZM", type: "website", images: [shareImage] },
    twitter: { card: "summary_large_image", title, description, images: [shareImage.url] },
  };
}
